using System.Collections.Generic;

public class TestFailedException : Exception
{
    public TestFailedException(string message) : base(message) { }
}

public static class Check
{
    public static void Equal<T>(T expected, T actual, string what)
    {
        if (!EqualityComparer<T>.Default.Equals(expected, actual))
            throw new TestFailedException($"{what}: expected {expected}, got {actual}");
    }
}

class Program
{
    static int Damage(int raw, int armor) => Math.Max(1, raw - armor);

    static void Main()
    {
        var tests = new Dictionary<string, Action>
        {
            ["normal hit"] = () => Check.Equal(20, Damage(30, 10), "normal hit"),
            ["armor bigger than hit"] = () => Check.Equal(1, Damage(5, 9), "small hit"),
            ["no hit"] = () => Check.Equal(0, Damage(0, 5), "no hit"),
        };
        foreach (var (name, test) in tests)
        {
            try { test(); Console.WriteLine($"PASS {name}"); }
            catch (TestFailedException ex) { Console.WriteLine($"FAIL {ex.Message}"); }
        }
    }
}

