using System;
using System.Collections.Generic;
using System.Linq;

public class TestFailedException : Exception
{
    public TestFailedException(string message) : base(message) { }
}

public static class Check
{
    public static void Equal<T>(T expected, T actual, string what)
    {
        // EqualityComparer handles null safely, unlike expected.Equals(actual).
        if (!EqualityComparer<T>.Default.Equals(expected, actual))
            throw new TestFailedException($"{what}: expected {expected}, got {actual}");
    }

    public static void True(bool condition, string what)
    {
        if (!condition) throw new TestFailedException($"{what}: expected true");
    }

    public static void Throws<TException>(Action action, string what) where TException : Exception
    {
        string want = typeof(TException).Name;
        try
        {
            action();
        }
        catch (TException)
        {
            return;   // exactly what we hoped for
        }
        catch (Exception e)
        {
            throw new TestFailedException($"{what}: expected {want}, got {e.GetType().Name}");
        }
        throw new TestFailedException($"{what}: expected {want}, nothing was thrown");
    }
}

