using System;
using System.Collections.Generic;
using System.Linq;

public static class ArmorMath
{
    public static int Damage(int raw, int armor)
    {
        if (raw <= 0) return 0;          // rule 1
        armor = Math.Max(0, armor);      // rule 2
        return Math.Max(1, raw - armor); // rule 3
    }
}

public static class ArmorTests
{
    public static bool AllPass(Func<int, int, int> damage)
    {
        // (raw, armor, expected): one normal case, then the edge of every rule.
        var cases = new (int Raw, int Armor, int Expected)[]
        {
            (30, 10, 20),   // normal hit
            (10, 0, 10),    // no armor at all
            (5, 9, 1),      // armor bigger than the hit: still 1
            (10, 10, 1),    // exactly equal: still 1
            (0, 5, 0),      // no hit, no damage
            (-4, 0, 0),     // negative raw counts as no hit
            (10, -5, 10),   // negative armor counts as 0
        };
        foreach (var c in cases)
            if (damage(c.Raw, c.Armor) != c.Expected) return false;
        return true;
    }
}

