using System;
using System.Collections.Generic;
using System.Linq;

// The code under test: don't change it.
public class Wallet
{
    public int Coins { get; private set; }

    public void Earn(int n)
    {
        if (n <= 0) throw new ArgumentOutOfRangeException(nameof(n));
        Coins += n;
    }

    public bool Spend(int n)
    {
        if (n > Coins) return false;
        Coins -= n;
        return true;
    }
}

public static class TestRunner
{
    public static string Run(Dictionary<string, Action> tests)
    {
        var failed = new List<string>();
        foreach (var (name, test) in tests)
        {
            try
            {
                test();
            }
            catch (Exception)
            {
                failed.Add(name);   // note it and carry on with the next test
            }
        }
        string summary = $"{tests.Count - failed.Count} passed, {failed.Count} failed";
        return failed.Count == 0 ? summary : summary + ": " + string.Join(", ", failed);
    }
}

public static class WalletTests
{
    public static Dictionary<string, Action> All() => new()
    {
        ["earning adds coins"] = () =>
        {
            var w = new Wallet();
            w.Earn(5);
            w.Earn(3);
            if (w.Coins != 8) throw new Exception($"expected 8, got {w.Coins}");
        },
        ["can't overspend"] = () =>
        {
            var w = new Wallet();
            w.Earn(3);
            if (w.Spend(10)) throw new Exception("spending 10 of 3 should fail");
            if (w.Coins != 3) throw new Exception("a failed spend must not change the coins");
        },
        ["spending exactly everything works"] = () =>
        {
            var w = new Wallet();
            w.Earn(4);
            if (!w.Spend(4) || w.Coins != 0) throw new Exception("should spend down to 0");
        },
        ["earning zero throws"] = () =>
        {
            try { new Wallet().Earn(0); }
            catch (ArgumentOutOfRangeException) { return; }
            throw new Exception("Earn(0) should throw");
        },
    };
}
